import{_ as e,C as t,c as i,o as a,j as s,b as r,a0 as n,a as l,w as o,G as d,a1 as u}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Objectifs SMART pour la pétanque","description":"","frontmatter":{},"headers":[],"relativePath":"fr/education/goals/smart-goals.md","filePath":"fr/education/goals/smart-goals.md"}');const p=e({name:"fr/education/goals/smart-goals.md"},[["render",function(e,c,p,m,h,f){const b=t("Mermaid");return a(),i("div",null,[c[1]||(c[1]=s("h1",{id:"objectifs-smart-pour-la-petanque",tabindex:"-1"},[l("Objectifs SMART pour la pétanque "),s("a",{class:"header-anchor",href:"#objectifs-smart-pour-la-petanque","aria-label":'Permalink to "Objectifs SMART pour la pétanque"'},"​")],-1)),c[2]||(c[2]=s("p",null,"La méthode SMART transforme les souhaits vagues en objectifs concrets. Examinons chaque élément en détail, avec des exemples spécifiques pour la pétanque.",-1)),c[3]||(c[3]=s("div",{class:"tip custom-block"},[s("p",{class:"custom-block-title"},"La grande idée"),s("p",null,"Des objectifs vagues mènent à des résultats vagues. Les objectifs SMART apportent clarté, action et progrès mesurables. Transformez votre désir de vous améliorer en objectifs précis et atteignables.")],-1)),(a(),r(u,null,{default:o(()=>[d(b,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BObjectif%20vague%5D%20--%3E%20B%5BAucune%20action%20claire%5D%0A%20%20%20%20B%20--%3E%20C%5BAucun%20progr%C3%A8s%5D%0A%0A%20%20%20%20D%5BObjectif%20SMART%5D%20--%3E%20E%5BPlan%20d%26%2339%3Baction%20clair%5D%0A%20%20%20%20E%20--%3E%20F%5BProgr%C3%A8s%20mesurables%5D%0A%20%20%20%20F%20--%3E%20G%5BR%C3%A9alisation%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffebee%0A%20%20%20%20style%20C%20fill%3A%23ffebee%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20G%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[4]||(c[4]=n('<h2 id="s-specifique" tabindex="-1">S - Spécifique <a class="header-anchor" href="#s-specifique" aria-label="Permalink to &quot;S - Spécifique&quot;">​</a></h2><p>Un objectif spécifique répond à ces questions :</p><ul><li>**Quel est exactement ce que je souhaite réaliser ?</li><li><strong>Où</strong> cela se passera-t-il ?</li><li><strong>Quels</strong> aspects sont concernés ?</li></ul><h3 id="rendre-les-objectifs-specifiques" tabindex="-1">Rendre les objectifs spécifiques <a class="header-anchor" href="#rendre-les-objectifs-specifiques" aria-label="Permalink to &quot;Rendre les objectifs spécifiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vague</th><th>Spécifique</th></tr></thead><tbody><tr><td>«Améliorer ma façon de pointer»</td><td>« Améliorer ma précision de pointage sur les surfaces de gravier à des distances de 7 à 9 mètres »</td></tr><tr><td>« Renforcez-vous mentalement »</td><td>« Développer une routine d&#39;avant-lancer constante que j&#39;utilise pour chaque lancer »</td></tr><tr><td>« Gagnez plus de matchs »</td><td>« Gagner au moins 60 % de mes matchs compétitifs cette saison »</td></tr></tbody></table><h3 id="liste-de-controle-de-specificite" tabindex="-1">Liste de contrôle de spécificité <a class="header-anchor" href="#liste-de-controle-de-specificite" aria-label="Permalink to &quot;Liste de contrôle de spécificité&quot;">​</a></h3><ul><li>[ ] Quelqu&#39;un d&#39;autre peut-il comprendre exactement ce que j&#39;essaie de faire ?</li><li>[ ] Ai-je défini les conditions (distance, surface, situation) ?</li><li>[ ] N&#39;existe-t-il qu&#39;une seule interprétation de cet objectif ?</li></ul><h2 id="m-mesurable" tabindex="-1">M - Mesurable <a class="header-anchor" href="#m-mesurable" aria-label="Permalink to &quot;M - Mesurable&quot;">​</a></h2><p>On ne peut gérer ce qu&#39;on ne peut mesurer. Des objectifs mesurables permettent de suivre les progrès et de savoir quand on a réussi.</p><h3 id="methodes-de-mesure-des-objectifs-en-petanque" tabindex="-1">Méthodes de mesure des objectifs en pétanque <a class="header-anchor" href="#methodes-de-mesure-des-objectifs-en-petanque" aria-label="Permalink to &quot;Méthodes de mesure des objectifs en pétanque&quot;">​</a></h3><p><strong>Mesures quantitatives :</strong></p><ul><li>Points marqués lors des exercices (ex. : 24/30)</li><li>Pourcentage de précision (ex. : taux de réussite de 75 %)</li><li>Distance de la cible (par exemple, en moyenne 30 cm du cric)</li><li>Cohérence (ex. : 3 séances réussies consécutives)</li></ul><p><strong>Utilisation des exercices d&#39;entraînement comme mesures :</strong></p><table tabindex="0"><thead><tr><th>Percer</th><th>Ce que cela mesure</th><th>Exemple cible</th></tr></thead><tbody><tr><td>Échelle de tir</td><td>Précision de tir sous pression</td><td>Atteignez 10 m en 30 boules.</td></tr><tr><td>Précision de pointage</td><td>Précision de pointage par rapport à la zone</td><td>24/30 points</td></tr><tr><td>Variation de distance</td><td>Contrôle de profondeur</td><td>80 % à moins de 50 cm</td></tr></tbody></table><h3 id="suivi-de-vos-mesures" tabindex="-1">Suivi de vos mesures <a class="header-anchor" href="#suivi-de-vos-mesures" aria-label="Permalink to &quot;Suivi de vos mesures&quot;">​</a></h3><p>Tenez un journal simple :</p><ul><li>Date</li><li>Exercice</li><li>Score/résultat</li><li>Conditions (surface, météo)</li><li>Notes</li></ul><h2 id="a-realisable-mais-difficile" tabindex="-1">A - Réalisable (mais difficile) <a class="header-anchor" href="#a-realisable-mais-difficile" aria-label="Permalink to &quot;A - Réalisable (mais difficile)&quot;">​</a></h2><p>Les objectifs doivent vous pousser à vous dépasser sans être impossibles.</p><h3 id="trouver-le-bon-niveau" tabindex="-1">Trouver le bon niveau <a class="header-anchor" href="#trouver-le-bon-niveau" aria-label="Permalink to &quot;Trouver le bon niveau&quot;">​</a></h3><p><strong>Trop facile :</strong> « Entraînez-vous une fois ce mois-ci »</p><ul><li>Pas de croissance, pas de motivation</li></ul><p><strong>Trop difficile :</strong> « Ne jamais rater un tir »</p><ul><li>L&#39;impossible engendre la frustration</li></ul><p><strong>Parfait :</strong> « Améliorez votre précision de tir de 15 % en 8 semaines »</p><ul><li>Difficile mais réaliste avec des efforts.</li></ul><h3 id="questions-pour-tester-la-faisabilite" tabindex="-1">Questions pour tester la faisabilité <a class="header-anchor" href="#questions-pour-tester-la-faisabilite" aria-label="Permalink to &quot;Questions pour tester la faisabilité&quot;">​</a></h3><ul><li>D&#39;autres personnes de mon niveau ont-elles réussi cela ?</li><li>Ai-je le temps et les ressources nécessaires ?</li><li>Est-ce que cela dépend (en grande partie) de moi ?</li><li>Suis-je prêt à faire ce qu&#39;il faut ?</li></ul><h3 id="objectifs-ambitieux" tabindex="-1">Objectifs ambitieux <a class="header-anchor" href="#objectifs-ambitieux" aria-label="Permalink to &quot;Objectifs ambitieux&quot;">​</a></h3><p>Il est normal d&#39;avoir des objectifs ambitieux à long terme. Assurez-vous simplement que vos objectifs à court terme constituent des étapes réalisables pour y parvenir.</p><h2 id="r-pertinent" tabindex="-1">R - Pertinent <a class="header-anchor" href="#r-pertinent" aria-label="Permalink to &quot;R - Pertinent&quot;">​</a></h2><p>Vos objectifs doivent être en accord avec votre vision d&#39;ensemble.</p><h3 id="questions-de-pertinence" tabindex="-1">Questions de pertinence <a class="header-anchor" href="#questions-de-pertinence" aria-label="Permalink to &quot;Questions de pertinence&quot;">​</a></h3><ul><li>Cet objectif contribue-t-il à mon développement global ?</li><li>Est-ce la priorité adéquate actuellement ?</li><li>Est-ce compatible avec le temps et les ressources dont je dispose ?</li><li>Suis-je réellement motivé par cet objectif ?</li></ul><h3 id="exemple-verification-de-la-pertinence" tabindex="-1">Exemple : Vérification de la pertinence <a class="header-anchor" href="#exemple-verification-de-la-pertinence" aria-label="Permalink to &quot;Exemple : Vérification de la pertinence&quot;">​</a></h3><p><strong>Situation :</strong> Vous souhaitez participer à des compétitions nationales.</p><p><strong>Objectifs pertinents :</strong></p><ul><li>Améliorer la précision de tir (impact direct sur les résultats)</li><li>Développer des routines mentales (utile dans les situations de pression)</li><li>Augmenter la fréquence d&#39;entraînement (développe les compétences plus rapidement)</li></ul><p><strong>Objectifs moins pertinents :</strong></p><ul><li>Apprenez les coups spéciaux (amusant, mais pas une priorité en compétition)</li><li>Achetez des boules neuves coûteuses (le matériel n&#39;est pas votre facteur limitant).</li></ul><h2 id="t-limite-dans-le-temps" tabindex="-1">T - Limité dans le temps <a class="header-anchor" href="#t-limite-dans-le-temps" aria-label="Permalink to &quot;T - Limité dans le temps&quot;">​</a></h2><p>Les échéances créent un sentiment d&#39;urgence et permettent de planifier.</p><h3 id="definition-des-echeanciers" tabindex="-1">Définition des échéanciers <a class="header-anchor" href="#definition-des-echeanciers" aria-label="Permalink to &quot;Définition des échéanciers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type d&#39;objectif</th><th>Délai typique</th></tr></thead><tbody><tr><td>à long terme</td><td>1 à 3 ans</td></tr><tr><td>Annuel</td><td>12 mois</td></tr><tr><td>Trimestriel</td><td>3 mois</td></tr><tr><td>Mensuel</td><td>4 semaines</td></tr><tr><td>Hebdomadaire</td><td>7 jours</td></tr><tr><td>Session</td><td>Pratique individuelle</td></tr></tbody></table><h3 id="exemple-de-chronologie" tabindex="-1">Exemple de chronologie <a class="header-anchor" href="#exemple-de-chronologie" aria-label="Permalink to &quot;Exemple de chronologie&quot;">​</a></h3><p><strong>À long terme (2 ans) :</strong> Se qualifier pour la sélection en équipe nationale</p><p><strong>Annuel :</strong> Terminer dans le top 10 des classements régionaux</p><p><strong>Trimestriel (T1) :</strong></p><ul><li>Établir une routine d&#39;entraînement régulière</li><li>Améliorer la précision de tir à 70 %</li></ul><p><strong>Mensuel (janvier) :</strong></p><ul><li>Semaine 1 : Évaluation du niveau actuel, définition des valeurs de référence</li><li>Semaines 2 et 3 : Se concentrer sur la technique de tir</li><li>Semaine 4 : Tester et mesurer les progrès</li></ul><p><strong>Hebdomadaire:</strong></p><ul><li>Lundi : Séance de tir technique</li><li>Mercredi : Pointage et situations de jeu</li><li>Vendredi : Entraînement mental et visualisation</li><li>Week-end : Compétition ou entraînement en match</li></ul><h2 id="synthese-du-tout" tabindex="-1">Synthèse du tout <a class="header-anchor" href="#synthese-du-tout" aria-label="Permalink to &quot;Synthèse du tout&quot;">​</a></h2><h3 id="feuille-de-travail-pour-la-definition-des-objectifs" tabindex="-1">Feuille de travail pour la définition des objectifs <a class="header-anchor" href="#feuille-de-travail-pour-la-definition-des-objectifs" aria-label="Permalink to &quot;Feuille de travail pour la définition des objectifs&quot;">​</a></h3><p><strong>Mon objectif (première ébauche) :</strong></p><hr><p><strong>Spécifique - Quoi exactement ?</strong></p><hr><p><strong>Mesurable - Comment le saurai-je ?</strong></p><hr><p><strong>Réalisable - Est-ce réaliste ?</strong></p><hr><p><strong>Pertinent - Pourquoi est-ce important ?</strong></p><hr><p><strong>Délai limité - Pour quand ?</strong></p><hr><p><strong>Mon objectif SMART (version finale) :</strong></p><hr><h3 id="exemple-complete" tabindex="-1">Exemple complété <a class="header-anchor" href="#exemple-complete" aria-label="Permalink to &quot;Exemple complété&quot;">​</a></h3><p><strong>Première ébauche :</strong> « Améliorer mon tir »</p><p><strong>Version SMART :</strong> « D’ici le 30 avril, j’atteindrai un score de 24/30 ou plus à l’exercice de tir à l’échelle (6-10 m avec obstacles) lors de trois séances d’entraînement consécutives, mesuré par mon journal d’entraînement. »</p><h2 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h2><blockquote><p>Les objectifs SMART transforment les rêves en plans et les plans en résultats.</p></blockquote><p>Prenez le temps de bien définir vos objectifs. Un objectif bien défini représente la moitié du chemin parcouru.</p>',75))])}]]);export{c as __pageData,p as default};
